arguments.content:
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'cover',
  index: 1,
  title: 'Global CO₂ Emissions: Trends, Regional Shifts, and Per Capita Inequalities'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Decorative diagonal shape - top right
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.5, y: 0, w: 3.5, h: 5.625,
    fill: { color: theme.secondary },
    rotate: 0
  });

  // Accent triangle shape
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.0, y: 0, w: 0.5, h: 5.625,
    fill: { color: theme.accent }
  });

  // Small decorative circles
  slide.addShape(pres.shapes.OVAL, {
    x: 7.0, y: 0.8, w: 1.2, h: 1.2,
    fill: { color: theme.accent, transparency: 60 }
  });
  slide.addShape(pres.shapes.OVAL, {
    x: 8.2, y: 3.5, w: 0.8, h: 0.8,
    fill: { color: theme.light, transparency: 50 }
  });

  // Main title
  slide.addText("Global CO₂ Emissions", {
    x: 0.6, y: 1.0, w: 5.2, h: 1.2,
    fontSize: 44, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left",
    margin: 0
  });

  // Subtitle line 1
  slide.addText("Trends, Regional Shifts, and\nPer Capita Inequalities", {
    x: 0.6, y: 2.2, w: 5.2, h: 1.0,
    fontSize: 24, fontFace: "Georgia",
    color: theme.accent, bold: false, align: "left",
    margin: 0
  });

  // Accent line
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.6, y: 3.4, w: 2.0, h: 0.04,
    fill: { color: theme.accent }
  });

  // Scope
  slide.addText("A Data-Driven Overview: 1750 – 2024", {
    x: 0.6, y: 3.6, w: 5.2, h: 0.5,
    fontSize: 16, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left",
    margin: 0
  });

  // Sources
  slide.addText("Data: Global Carbon Budget 2025  |  NASA Vital Signs", {
    x: 0.6, y: 4.8, w: 5.2, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "CCCCCC", bold: false, align: "left",
    margin: 0
  });

  // Right panel content - key number
  slide.addText("429", {
    x: 7.0, y: 1.8, w: 2.5, h: 1.2,
    fontSize: 72, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "center", valign: "middle",
    margin: 0
  });
  slide.addText("ppm CO₂ (Feb 2026)", {
    x: 7.0, y: 2.9, w: 2.5, h: 0.5,
    fontSize: 14, fontFace: "Calibri",
    color: theme.accent, bold: false, align: "center",
    margin: 0
  });

  // Year badge
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 7.5, y: 3.8, w: 1.5, h: 0.4,
    fill: { color: theme.light },
    rectRadius: 0.2
  });
  slide.addText("1750 – 2024", {
    x: 7.5, y: 3.8, w: 1.5, h: 0.4,
    fontSize: 13, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle",
    margin: 0
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "283618", secondary: "606c38", accent: "dda15e", light: "bc6c25", bg: "fefae0" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-01-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

