arguments.content:
const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 2,
  title: 'Atmospheric CO₂ Reaches 429 ppm — 50% Above Pre-Industrial Levels'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Atmospheric CO₂ Reaches 429 ppm", {
    x: 0.5, y: 0.3, w: 9, h: 0.6,
    fontSize: 32, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0
  });

  // Subtitle
  slide.addText("50% Above Pre-Industrial Levels", {
    x: 0.5, y: 0.9, w: 9, h: 0.4,
    fontSize: 18, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", margin: 0
  });

  // Main stat card background
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.6, w: 4.2, h: 2.8,
    fill: { color: theme.primary }
  });

  // Big number
  slide.addText("429", {
    x: 0.5, y: 1.7, w: 4.2, h: 1.6,
    fontSize: 80, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "center", valign: "middle",
    margin: 0
  });

  // ppm label
  slide.addText("parts per million", {
    x: 0.5, y: 3.2, w: 4.2, h: 0.4,
    fontSize: 16, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "center", margin: 0
  });

  // Date
  slide.addText("February 2026 — Mauna Loa Observatory", {
    x: 0.5, y: 3.6, w: 4.2, h: 0.4,
    fontSize: 12, fontFace: "Calibri",
    color: "CCCCCC", bold: false, align: "center", margin: 0
  });

  // 50% badge
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 1.5, y: 4.15, w: 2.2, h: 0.45,
    fill: { color: theme.light },
    rectRadius: 0.22
  });
  slide.addText("+50% from pre-industrial", {
    x: 1.5, y: 4.15, w: 2.2, h: 0.45,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle", margin: 0
  });

  // Right panel - timeline and context
  // Timeline card
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.2, y: 1.6, w: 4.3, h: 2.8,
    fill: { color: "FFFFFF" }
  });

  // Timeline title
  slide.addText("Context & Acceleration", {
    x: 5.5, y: 1.7, w: 3.8, h: 0.4,
    fontSize: 16, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0
  });

  // Timeline items
  const timelineItems = [
    { year: "~1750", desc: "Pre-industrial baseline: ~280 ppm", color: theme.secondary },
    { year: "1958", desc: "Keeling Curve begins: ~315 ppm", color: theme.secondary },
    { year: "2026", desc: "Current level: 429 ppm", color: theme.light }
  ];

  timelineItems.forEach((item, i) => {
    const yBase = 2.25 + i * 0.65;
    // Dot
    slide.addShape(pres.shapes.OVAL, {
      x: 5.5, y: yBase + 0.08, w: 0.18, h: 0.18,
      fill: { color: item.color }
    });
    // Line connecting dots
    if (i < timelineItems.length - 1) {
      slide.addShape(pres.shapes.RECTANGLE, {
        x: 5.57, y: yBase + 0.26, w: 0.04, h: 0.47,
        fill: { color: theme.secondary, transparency: 50 }
      });
    }
    // Year
    slide.addText(item.year, {
      x: 5.85, y: yBase, w: 1.0, h: 0.3,
      fontSize: 13, fontFace: "Georgia",
      color: theme.primary, bold: true, align: "left", margin: 0
    });
    // Description
    slide.addText(item.desc, {
      x: 6.85, y: yBase, w: 2.5, h: 0.3,
      fontSize: 12, fontFace: "Calibri",
      color: theme.secondary, bold: false, align: "left", margin: 0
    });
  });

  // Bottom insight
  slide.addText("The current increase is at least 1.5× the natural rise at the end of the last ice age — a change that took thousands of years then but has occurred in roughly two centuries now.", {
    x: 5.5, y: 3.7, w: 3.8, h: 0.6,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", margin: 0,
    italic: true
  });

  // Source
  slide.addText("Source: NOAA Mauna Loa Observatory / NASA Vital Signs", {
    x: 0.5, y: 5.15, w: 6, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", margin: 0,
    italic: true
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.primary }
  });
  slide.addText("2", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "283618", secondary: "606c38", accent: "dda15e", light: "bc6c25", bg: "fefae0" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-02-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

