const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 3,
  title: 'Global Fossil Fuel CO₂ Emissions Grew Six-Fold: 6 Billion to 35+ Billion Tonnes'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Global Fossil Fuel CO₂ Emissions Grew Six-Fold", {
    x: 0.5, y: 0.3, w: 9, h: 0.5,
    fontSize: 28, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0
  });
  slide.addText("6 Billion to 35+ Billion Tonnes (1950–2024)", {
    x: 0.5, y: 0.8, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", margin: 0
  });

  // Image on left
  slide.addImage({
    path: "./imgs/figure_3.jpg",
    x: 0.5, y: 1.4, w: 5.5, h: 3.2,
    sizing: { type: 'contain', w: 5.5, h: 3.2 }
  });

  // Right panel - key milestones
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 6.3, y: 1.4, w: 3.2, h: 3.2,
    fill: { color: "FFFFFF" }
  });

  slide.addText("Key Milestones", {
    x: 6.5, y: 1.5, w: 2.8, h: 0.4,
    fontSize: 16, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0
  });

  // Milestone 1
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 6.5, y: 2.0, w: 2.8, h: 0.7,
    fill: { color: theme.primary },
    rectRadius: 0.03
  });
  slide.addText("1950", {
    x: 6.6, y: 2.02, w: 0.8, h: 0.3,
    fontSize: 14, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "left", margin: 0
  });
  slide.addText("~6 Bt CO₂", {
    x: 6.6, y: 2.32, w: 2.6, h: 0.3,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", margin: 0
  });

  // Milestone 2
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 6.5, y: 2.85, w: 2.8, h: 0.7,
    fill: { color: theme.secondary },
    rectRadius: 0.03
  });
  slide.addText("1990", {
    x: 6.6, y: 2.87, w: 0.8, h: 0.3,
    fontSize: 14, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "left", margin: 0
  });
  slide.addText(">20 Bt CO₂", {
    x: 6.6, y: 3.17, w: 2.6, h: 0.3,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", margin: 0
  });

  // Milestone 3
  slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
    x: 6.5, y: 3.7, w: 2.8, h: 0.7,
    fill: { color: theme.light },
    rectRadius: 0.03
  });
  slide.addText("2024", {
    x: 6.6, y: 3.72, w: 0.8, h: 0.3,
    fontSize: 14, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left", margin: 0
  });
  slide.addText(">35 Bt CO₂", {
    x: 6.6, y: 4.02, w: 2.6, h: 0.3,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", margin: 0
  });

  // Bottom note
  slide.addText("Growth remained slow until the mid-20th century, then accelerated sharply. While growth has slowed in recent years, emissions have not yet peaked.", {
    x: 0.5, y: 4.75, w: 9, h: 0.5,
    fontSize: 11, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", margin: 0,
    italic: true
  });

  // Source
  slide.addText("Source: Our World in Data — Global Carbon Budget 2025", {
    x: 0.5, y: 5.15, w: 6, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", margin: 0,
    italic: true
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.primary }
  });
  slide.addText("3", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "283618", secondary: "606c38", accent: "dda15e", light: "bc6c25", bg: "fefae0" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-03-preview.pptx" });
}

