const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 4,
  title: 'China Now Emits Over 12 Billion Tonnes — More Than Double the United States'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("China Now Emits Over 12 Billion Tonnes", {
    x: 0.5, y: 0.3, w: 9, h: 0.5,
    fontSize: 28, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0
  });
  slide.addText("More Than Double the United States", {
    x: 0.5, y: 0.8, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", margin: 0
  });

  // Left: Country comparison bars
  const barData = [
    { name: "China", value: 12.5, pct: 27, color: theme.light },
    { name: "United States", value: 5.0, pct: 14, color: theme.secondary },
    { name: "India", value: 3.0, pct: 8, color: theme.secondary },
    { name: "EU-27", value: 2.7, pct: 7, color: theme.secondary },
    { name: "Germany", value: 0.6, pct: 1.7, color: theme.accent },
    { name: "United Kingdom", value: 0.3, pct: 0.9, color: theme.accent },
    { name: "Brazil", value: 0.5, pct: 1.4, color: theme.accent },
    { name: "France", value: 0.3, pct: 0.8, color: theme.accent }
  ];

  const startY = 1.4;
  const barHeight = 0.35;
  const barGap = 0.1;
  const maxBarW = 4.0;

  barData.forEach((item, i) => {
    const yPos = startY + i * (barHeight + barGap);
    const barW = Math.max(0.3, (item.value / 12.5) * maxBarW);

    // Country name
    slide.addText(item.name, {
      x: 0.5, y: yPos, w: 1.6, h: barHeight,
      fontSize: 11, fontFace: "Calibri",
      color: theme.primary, bold: true, align: "right", valign: "middle", margin: 0
    });

    // Bar
    slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: 2.2, y: yPos, w: barW, h: barHeight,
      fill: { color: item.color },
      rectRadius: 0.02
    });

    // Value label
    slide.addText(item.value.toFixed(1) + " Bt  (" + item.pct + "%)", {
      x: 2.25 + barW + 0.08, y: yPos, w: 1.8, h: barHeight,
      fontSize: 10, fontFace: "Calibri",
      color: theme.primary, bold: false, align: "left", valign: "middle", margin: 0
    });
  });

  // Right panel: Image
  slide.addImage({
    path: "./imgs/figure_3.jpg",
    x: 5.5, y: 1.4, w: 4.0, h: 3.0,
    sizing: { type: 'contain', w: 4.0, h: 3.0 }
  });

  // Key insight box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.5, y: 4.55, w: 4.0, h: 0.55,
    fill: { color: theme.primary }
  });
  slide.addText("China's steep rise post-2000 contrasts with the US decline from its ~6 Bt peak around 2005.", {
    x: 5.65, y: 4.57, w: 3.7, h: 0.5,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", valign: "middle", margin: 0
  });

  // Source
  slide.addText("Source: Our World in Data — Global Carbon Budget 2025", {
    x: 0.5, y: 5.15, w: 6, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", margin: 0,
    italic: true
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.primary }
  });
  slide.addText("4", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "283618", secondary: "606c38", accent: "dda15e", light: "bc6c25", bg: "fefae0" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-04-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

