const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 5,
  title: 'Asia Now Accounts for ~50% of Global Emissions; US + Europe Below One-Third'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Asia Now Accounts for ~50% of Global Emissions", {
    x: 0.5, y: 0.3, w: 9, h: 0.5,
    fontSize: 28, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0
  });
  slide.addText("US + Europe Below One-Third", {
    x: 0.5, y: 0.8, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", margin: 0
  });

  // Side-by-side comparison: 1900 vs 2024
  // Left card: 1900
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 1.5, w: 4.2, h: 3.5,
    fill: { color: "FFFFFF" }
  });
  slide.addText("1900", {
    x: 0.5, y: 1.55, w: 4.2, h: 0.6,
    fontSize: 40, fontFace: "Georgia",
    color: theme.secondary, bold: true, align: "center", valign: "middle", margin: 0
  });

  // Stacked bar 1900 - visual approximation
  const barX = 1.3;
  const barW = 2.6;
  const barY = 2.3;
  const barH = 2.2;

  // Europe + US: >90%
  const euUs1900 = barH * 0.90;
  // Rest: ~10%
  const rest1900 = barH * 0.10;

  slide.addShape(pres.shapes.RECTANGLE, {
    x: barX, y: barY, w: barW, h: euUs1900,
    fill: { color: theme.secondary }
  });
  slide.addText("Europe + US\n>90%", {
    x: barX, y: barY + 0.3, w: barW, h: 1.0,
    fontSize: 14, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle", margin: 0
  });

  slide.addShape(pres.shapes.RECTANGLE, {
    x: barX, y: barY + euUs1900, w: barW, h: rest1900,
    fill: { color: theme.accent }
  });
  slide.addText("Rest ~10%", {
    x: barX, y: barY + euUs1900 - 0.05, w: barW, h: rest1900 + 0.05,
    fontSize: 9, fontFace: "Calibri",
    color: theme.primary, bold: false, align: "center", valign: "bottom", margin: 0
  });

  // Right card: 2024
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 1.5, w: 4.2, h: 3.5,
    fill: { color: "FFFFFF" }
  });
  slide.addText("2024", {
    x: 5.3, y: 1.55, w: 4.2, h: 0.6,
    fontSize: 40, fontFace: "Georgia",
    color: theme.light, bold: true, align: "center", valign: "middle", margin: 0
  });

  // Stacked bar 2024
  const barX2 = 6.1;
  const barW2 = 2.6;
  const barY2 = 2.3;
  const barH2 = 2.2;

  // Asia: ~50%
  const asia2024 = barH2 * 0.50;
  // US + Europe: <33%
  const usEu2024 = barH2 * 0.32;
  // Africa + S. America: ~7%
  const afrSa2024 = barH2 * 0.07;
  // Other: ~11%
  const other2024 = barH2 * 0.11;

  let curY = barY2;

  slide.addShape(pres.shapes.RECTANGLE, {
    x: barX2, y: curY, w: barW2, h: asia2024,
    fill: { color: theme.light }
  });
  slide.addText("Asia ~50%", {
    x: barX2, y: curY + 0.1, w: barW2, h: 0.5,
    fontSize: 13, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle", margin: 0
  });
  curY += asia2024;

  slide.addShape(pres.shapes.RECTANGLE, {
    x: barX2, y: curY, w: barW2, h: usEu2024,
    fill: { color: theme.secondary }
  });
  slide.addText("US + Europe <33%", {
    x: barX2, y: curY + 0.05, w: barW2, h: 0.45,
    fontSize: 12, fontFace: "Calibri",
    color: "FFFFFF", bold: true, align: "center", valign: "middle", margin: 0
  });
  curY += usEu2024;

  slide.addShape(pres.shapes.RECTANGLE, {
    x: barX2, y: curY, w: barW2, h: other2024,
    fill: { color: theme.accent }
  });
  slide.addText("Other ~11%", {
    x: barX2, y: curY, w: barW2, h: other2024,
    fontSize: 9, fontFace: "Calibri",
    color: theme.primary, bold: false, align: "center", valign: "middle", margin: 0
  });
  curY += other2024;

  slide.addShape(pres.shapes.RECTANGLE, {
    x: barX2, y: curY, w: barW2, h: afrSa2024,
    fill: { color: theme.primary }
  });
  slide.addText("Africa + S. America 3-4% each", {
    x: barX2, y: curY, w: barW2, h: afrSa2024,
    fontSize: 8, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "center", valign: "middle", margin: 0
  });

  // Arrow between cards
  slide.addText("→", {
    x: 4.5, y: 2.7, w: 1.0, h: 0.8,
    fontSize: 36, fontFace: "Georgia",
    color: theme.accent, bold: true, align: "center", valign: "middle", margin: 0
  });

  // Bottom insight
  slide.addText("In 1900, Europe and the US accounted for >90% of global emissions. By 1950, still >85%. Today, Asia — home to nearly 60% of the world's population — produces roughly half.", {
    x: 0.5, y: 5.1, w: 8.5, h: 0.4,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", margin: 0,
    italic: true
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.primary }
  });
  slide.addText("5", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "283618", secondary: "606c38", accent: "dda15e", light: "bc6c25", bg: "fefae0" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-05-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

