const slideConfig = {
  type: 'content',
  index: 6,
  title: 'Per Capita Gap: 15 t in the US vs. 0.1 t in Chad — a 150× Disparity'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Per Capita Gap: 150× Disparity", {
    x: 0.5, y: 0.3, w: 9, h: 0.5,
    fontSize: 28, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0
  });
  slide.addText("15 t in the US vs. 0.1 t in Chad", {
    x: 0.5, y: 0.8, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", margin: 0
  });

  // Horizontal bar chart - left panel
  const barData = [
    { name: "United States", value: 15, color: theme.light },
    { name: "Canada", value: 13, color: theme.light },
    { name: "China", value: 9, color: theme.secondary },
    { name: "EU-27", value: 7, color: theme.secondary },
    { name: "World avg.", value: 5, color: theme.accent },
    { name: "United Kingdom", value: 4, color: theme.accent },
    { name: "India", value: 2, color: theme.primary },
    { name: "Kenya", value: 0.8, color: theme.primary }
  ];

  const chartLeft = 2.0;
  const maxBarW = 4.5;
  const barH = 0.32;
  const barGap = 0.12;
  const startY = 1.4;

  barData.forEach((item, i) => {
    const yPos = startY + i * (barH + barGap);
    const barW = Math.max(0.15, (item.value / 15) * maxBarW);

    // Country name
    slide.addText(item.name, {
      x: 0.5, y: yPos, w: 1.4, h: barH,
      fontSize: 11, fontFace: "Calibri",
      color: theme.primary, bold: true, align: "right", valign: "middle", margin: 0
    });

    // Bar
    slide.addShape(pres.shapes.ROUNDED_RECTANGLE, {
      x: chartLeft, y: yPos, w: barW, h: barH,
      fill: { color: item.color },
      rectRadius: 0.02
    });

    // Value label
    const valText = item.value >= 1 ? item.value.toFixed(0) + " t" : item.value.toFixed(1) + " t";
    slide.addText(valText, {
      x: chartLeft + barW + 0.08, y: yPos, w: 1.0, h: barH,
      fontSize: 10, fontFace: "Calibri",
      color: theme.primary, bold: false, align: "left", valign: "middle", margin: 0
    });
  });

  // World average line indicator
  const worldBarW = (5 / 15) * maxBarW;
  slide.addShape(pres.shapes.RECTANGLE, {
    x: chartLeft + worldBarW, y: startY - 0.08, w: 0.03, h: barData.length * (barH + barGap) + 0.08,
    fill: { color: theme.accent }
  });

  // Right panel: figure_1.jpg
  slide.addImage({
    path: "./imgs/figure_1.jpg",
    x: 6.8, y: 1.3, w: 2.8, h: 2.5,
    sizing: { type: 'contain', w: 2.8, h: 2.5 }
  });

  // Caption for image
  slide.addText("Per capita CO₂ emissions over time", {
    x: 6.8, y: 3.85, w: 2.8, h: 0.3,
    fontSize: 9, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "center", margin: 0,
    italic: true
  });

  // Bottom insight box
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.4, w: 9.0, h: 0.6,
    fill: { color: theme.primary }
  });
  slide.addText("The average American emits in under two days what the average person in Chad or Niger emits in an entire year. Countries with similar living standards can differ significantly — France and the UK have much lower per capita emissions than Germany or the Netherlands.", {
    x: 0.7, y: 4.42, w: 8.6, h: 0.55,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", valign: "middle", margin: 0
  });

  // Source
  slide.addText("Source: Our World in Data — Global Carbon Budget 2025", {
    x: 0.5, y: 5.15, w: 6, h: 0.3,
    fontSize: 10, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", margin: 0,
    italic: true
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.primary }
  });
  slide.addText("6", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "283618", secondary: "606c38", accent: "dda15e", light: "bc6c25", bg: "fefae0" };
