    x: 0.5, y: 4.4, w: 9.0, h: 0.6,
    fill: { color: theme.primary }
  });
  slide.addText("The average American emits in under two days what the average person in Chad or Niger emits in an entire year. Countries with similar living standards can differ significantly — France and the UK have much lower per capita emissions than Germany or the Netherlands.", {
