const pptxgen = require("pptxgenjs");

const slideConfig = {
  type: 'content',
  index: 8,
  title: 'Energy Mix Explains Why France Emits Far Less Per Capita Than Germany'
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  // Title
  slide.addText("Energy Mix Explains Per Capita Differences", {
    x: 0.5, y: 0.3, w: 9, h: 0.5,
    fontSize: 28, fontFace: "Georgia",
    color: theme.primary, bold: true, align: "left", margin: 0
  });
  slide.addText("France and the UK emit far less per capita than Germany or the Netherlands", {
    x: 0.5, y: 0.8, w: 9, h: 0.4,
    fontSize: 14, fontFace: "Calibri",
    color: theme.secondary, bold: false, align: "left", margin: 0
  });

  // Comparison table - France/UK vs Germany/Netherlands
  const tableX = 0.5;
  const tableY = 1.5;
  const tableW = 9.0;
  const colWidths = [2.2, 1.7, 1.7, 1.7, 1.7];

  // Header row
  const headerRow = [
    { text: "Country", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 12, fontFace: "Calibri", align: "center" } },
