    { text: "Fossil Fuels", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 12, fontFace: "Calibri", align: "center" } },
    { text: "Per Capita CO₂", options: { fill: { color: theme.primary }, color: "FFFFFF", bold: true, fontSize: 12, fontFace: "Calibri", align: "center" } }
  ];

  // Data rows
  const rowFrance = [
    { text: "France", options: { fill: { color: "FFFFFF" }, color: theme.primary, bold: true, fontSize: 12, fontFace: "Calibri", align: "left" } },
    { text: "High", options: { fill: { color: "FFFFFF" }, color: theme.secondary, bold: false, fontSize: 11, fontFace: "Calibri", align: "center" } },
    { text: "Moderate", options: { fill: { color: "FFFFFF" }, color: theme.secondary, bold: false, fontSize: 11, fontFace: "Calibri", align: "center" } },
    { text: "Low", options: { fill: { color: "FFFFFF" }, color: theme.secondary, bold: false, fontSize: 11, fontFace: "Calibri", align: "center" } },
    { text: "~4 t", options: { fill: { color: "FFFFFF" }, color: theme.primary, bold: true, fontSize: 12, fontFace: "Calibri", align: "center" } }
  ];

  const rowUK = [
    { text: "United Kingdom", options: { fill: { color: theme.bg }, color: theme.primary, bold: true, fontSize: 12, fontFace: "Calibri", align: "left" } },
    { text: "Moderate", options: { fill: { color: theme.bg }, color: theme.secondary, bold: false, fontSize: 11, fontFace: "Calibri", align: "center" } },
    { text: "Growing", options: { fill: { color: theme.bg }, color: theme.secondary, bold: false, fontSize: 11, fontFace: "Calibri", align: "center" } },
    { text: "Declining", options: { fill: { color: theme.bg }, color: theme.secondary, bold: false, fontSize: 11, fontFace: "Calibri", align: "center" } },
    { text: "~4 t", options: { fill: { color: theme.bg }, color: theme.primary, bold: true, fontSize: 12, fontFace: "Calibri", align: "center" } }
  ];

  const rowGermany = [
    { text: "Germany", options: { fill: { color: "FFFFFF" }, color: theme.primary, bold: true, fontSize: 12, fontFace: "Calibri", align: "left" } },
    { text: "Low (phase-out)", options: { fill: { color: "FFFFFF" }, color: theme.light, bold: false, fontSize: 11, fontFace: "Calibri", align: "center" } },
    { text: "Growing", options: { fill: { color: "FFFFFF" }, color: theme.secondary, bold: false, fontSize: 11, fontFace: "Calibri", align: "center" } },
    { text: "Higher", options: { fill: { color: "FFFFFF" }, color: theme.light, bold: false, fontSize: 11, fontFace: "Calibri", align: "center" } },
    { text: "~8 t", options: { fill: { color: "FFFFFF" }, color: theme.light, bold: true, fontSize: 12, fontFace: "Calibri", align: "center" } }
  ];

  const rowNetherlands = [
    { text: "Netherlands", options: { fill: { color: theme.bg }, color: theme.primary, bold: true, fontSize: 12, fontFace: "Calibri", align: "left" } },
    { text: "Low", options: { fill: { color: theme.bg }, color: theme.light, bold: false, fontSize: 11, fontFace: "Calibri", align: "center" } },
    { text: "Moderate", options: { fill: { color: theme.bg }, color: theme.secondary, bold: false, fontSize: 11, fontFace: "Calibri", align: "center" } },
    { text: "Higher", options: { fill: { color: theme.bg }, color: theme.light, bold: false, fontSize: 11, fontFace: "Calibri", align: "center" } },
    { text: "~8 t", options: { fill: { color: theme.bg }, color: theme.light, bold: true, fontSize: 12, fontFace: "Calibri", align: "center" } }
  ];

  slide.addTable([headerRow, rowFrance, rowUK, rowGermany, rowNetherlands], {
    x: tableX, y: tableY, w: tableW,
    colW: colWidths,
    border: { pt: 0.5, color: "DDDDDD" },
    rowH: [0.4, 0.4, 0.4, 0.4, 0.4]
  });

  // Left callout box - France/UK
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 3.8, w: 4.2, h: 1.1,
    fill: { color: theme.secondary }
  });
  slide.addText("France & UK", {
    x: 0.65, y: 3.85, w: 3.9, h: 0.3,
    fontSize: 14, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left", margin: 0
  });
  slide.addText("Higher nuclear and renewable shares drive per capita emissions to ~4 t — roughly half that of Germany and the Netherlands.", {
    x: 0.65, y: 4.15, w: 3.9, h: 0.65,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", margin: 0
  });

  // Right callout box - Germany/Netherlands
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 5.3, y: 3.8, w: 4.2, h: 1.1,
    fill: { color: theme.light }
  });
  slide.addText("Germany & Netherlands", {
    x: 5.45, y: 3.85, w: 3.9, h: 0.3,
    fontSize: 14, fontFace: "Georgia",
    color: "FFFFFF", bold: true, align: "left", margin: 0
  });
  slide.addText("Higher reliance on fossil fuels (especially coal and gas) pushes per capita emissions to ~8 t — despite comparable prosperity levels.", {
    x: 5.45, y: 4.15, w: 3.9, h: 0.65,
    fontSize: 10, fontFace: "Calibri",
    color: "FFFFFF", bold: false, align: "left", margin: 0
  });

  // Key insight
  slide.addText("Key Insight: Policy and energy mix choices — not just prosperity — determine per capita outcomes.", {
    x: 0.5, y: 5.05, w: 9, h: 0.3,
    fontSize: 11, fontFace: "Calibri",
    color: theme.primary, bold: true, align: "left", margin: 0,
    italic: true
  });

  // Page badge
  slide.addShape(pres.shapes.OVAL, {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fill: { color: theme.primary }
  });
  slide.addText("8", {
    x: 9.3, y: 5.1, w: 0.4, h: 0.4,
    fontSize: 12, fontFace: "Arial",
    color: "FFFFFF", bold: true, align: "center", valign: "middle"
  });

  return slide;
}

if (require.main === module) {
  const pres = new pptxgen();
  pres.layout = 'LAYOUT_16x9';
  const theme = { primary: "283618", secondary: "606c38", accent: "dda15e", light: "bc6c25", bg: "fefae0" };
  createSlide(pres, theme);
  pres.writeFile({ fileName: "slide-08-preview.pptx" });
}

module.exports = { createSlide, slideConfig };

