raw_arguments.content:
const pptxgen = require('pptxgenjs');
const pres = new pptxgen();
pres.layout = 'LAYOUT_16x9';
pres.title = 'Global CO₂ Emissions: Trends, Regional Shifts, and Per Capita Inequalities';
pres.author = 'Global Carbon Budget 2025 / NASA';

const theme = {
  primary: "283618",
  secondary: "606c38",
  accent: "dda15e",
  light: "bc6c25",
  bg: "fefae0"
};

for (let i = 1; i <= 9; i++) {
  const num = String(i).padStart(2, '0');
  const slideModule = require(`./slide-${num}.js`);
  slideModule.createSlide(pres, theme);
}

pres.writeFile({ fileName: './output/final_deck.pptx' })
  .then(() => console.log('Presentation saved to ./output/final_deck.pptx'))
  .catch(err => console.error('Error:', err));
